import json,math,re
from pathlib import Path
import numpy as np
root=Path('/home/work/user-job-dir/app/slai/user-xiexinyuan/xinyuan/precision-skill/precision-skills-publish/projects/precision-repair/cases/pretrained-training-repair-20261024T141838Z');summary=json.loads((root/'summary.json').read_text());paths={k:Path(summary[k+'_run']) for k in ['before','after']};report={}
for phase,p in paths.items():
 ss=dd=xx=yy=xy=0.;count=0;maximum=0.;equal=True
 for name in ['layer31-down-grad','head-target-grad']:
  a=np.load(p/'artifacts'/('trainer-'+name+'.npy'),mmap_mode='r').reshape(-1);b=np.load(p/'artifacts'/('oracle-'+name+'.npy'),mmap_mode='r').reshape(-1);assert a.shape==b.shape;count+=a.size
  for offset in range(0,a.size,1000000):
   x=np.asarray(a[offset:offset+1000000],dtype=np.float64);y=np.asarray(b[offset:offset+1000000],dtype=np.float64);assert np.isfinite(x).all() and np.isfinite(y).all();e=x-y;dd+=float(np.sum(e*e));xx+=float(np.sum(x*x));yy+=float(np.sum(y*y));xy+=float(np.sum(x*y));maximum=max(maximum,float(np.abs(e).max()));equal=equal and np.array_equal(x,y)
  if phase=='after':
   base=np.load(paths['before']/'artifacts'/('oracle-'+name+'.npy'),mmap_mode='r').reshape(-1);assert np.array_equal(base,b),'oracle changed'
 metrics=summary[phase+'_gradient_metrics'];assert count==metrics['count']==50458624;norm=math.sqrt(dd);assert math.isclose(norm,metrics['error_norm']['value'],rel_tol=1e-12,abs_tol=1e-12);assert maximum==metrics['max_abs']['value']
 cosine=xy/math.sqrt(xx*yy);assert math.isclose(cosine,metrics['cosine']['value'],rel_tol=1e-12,abs_tol=1e-12)
 text=(p/'stdout.bin').read_text();observed=math.fsum(map(float,re.findall(r'^TRAIN_MICRO (\S+)',text,re.M)));oracle=math.fsum(map(float,re.findall(r'^ORACLE_MICRO (\S+)',text,re.M)));assert observed==summary[phase]['loss'] and oracle==summary[phase]['oracle_loss'];report[phase]={'count':count,'error_norm':norm,'max_abs':maximum,'cosine':cosine,'exact_equal':equal,'loss':observed,'oracle_loss':oracle}
assert report['before']['error_norm']>0 and report['after']['exact_equal'];assert summary['after']['valid_next_token_targets']==35
for phase in ['before','after']:
 tests=json.loads((root/('cpu-'+phase+'.json')).read_text());assert tests['passed']==(phase=='after')
print(json.dumps({'status':'passed','scope':'Independent NumPy audit of all saved gradient coordinates and terminal loss values; original and final oracle gradients exactly match. No model rerun.','phases':report},indent=2))
